export const HISTORY_LIMIT = 100;
export function buildSubscribeMessage(live) { const metric_names = (live.metricNames || '').split(',').map(value => value.trim()).filter(Boolean); const dimensions = (live.dimensions || '').split(',').reduce((result, entry) => { const [key, ...rest] = entry.split('='); const value = rest.join('=').trim(); if (key?.trim() && value) result[key.trim()] = value; return result; }, {}); const subscription = { action: 'subscribe' }; if (metric_names.length) subscription.metric_names = metric_names; if (Object.keys(dimensions).length) subscription.dimensions = dimensions; return subscription; }
function normalize(record) { const timestamp = record.timestamp; const metricName = record.metricName || record.metric_name || record.name; const value = record.value; return timestamp && typeof metricName === 'string' && Number.isFinite(Number(value)) ? { timestamp: new Date(timestamp).toISOString(), metricName, value: Number(value), dimensions: record.dimensions && typeof record.dimensions === 'object' ? record.dimensions : {} } : null; }
export function parseLiveFrame(frame) { try { const value = typeof frame === 'string' ? JSON.parse(frame) : frame; const records = Array.isArray(value) ? value : value.metrics || value.batch || value.observations || []; if (!Array.isArray(records)) return { observations: [], error: null }; return { observations: records.map(normalize).filter(Boolean), error: null }; } catch (_) { return { observations: [], error: 'Received an invalid live metric frame.' }; } }
export function addObservations(series, observations) { const next = { ...series }; observations.forEach(observation => { const previous = next[observation.metricName] || []; const withoutDuplicate = previous.filter(point => point.timestamp !== observation.timestamp); next[observation.metricName] = [...withoutDuplicate, observation].sort((a, b) => a.timestamp.localeCompare(b.timestamp)).slice(-HISTORY_LIMIT); }); return next; }
